from django.db import migrations, models


def number_warehouse_codes(apps, schema_editor):
    """Warehouse codes become numbers: each store's warehouses are numbered
    1, 2, 3 ... in the order they were made. Codes are only shown, never
    matched on (Smartlane's own warehouse code lives on its connection)."""
    Warehouse = apps.get_model("wms", "Warehouse")
    org_ids = Warehouse.objects.values_list("organization_id", flat=True).distinct()
    for org_id in org_ids:
        warehouses = list(Warehouse.objects.filter(organization_id=org_id).order_by("created_at", "id"))
        if all((w.code or "").isdigit() for w in warehouses):
            continue
        # Two steps - the code is unique per store, so a final number can't
        # be given while another warehouse may still hold it.
        for w in warehouses:
            w.code = f"tmp-{w.id}"
            w.save(update_fields=["code"])
        for n, w in enumerate(warehouses, start=1):
            w.code = str(n)
            w.save(update_fields=["code"])


